public class ProducerConsumerQueue {
    private final java.util.Queue<String> queue = new java.util.LinkedList<>();
    private final int capacity = 5;

    public void produce(String item) throws InterruptedException {
        synchronized (queue) {
            while (queue.size() == capacity) {
                // Releases lock and waits for consumer signal
                queue.wait();
            }
            queue.add(item);
            // Wakes up waiting consumers
            queue.notifyAll();
        }
    }

    public String consume() throws InterruptedException {
        synchronized (queue) {
            while (queue.isEmpty()) {
                // Using sleep() here would cause a deadlock as the lock remains held!
                queue.wait();
            }
            String item = queue.poll();
            queue.notifyAll();
            return item;
        }
    }
}
